import { readFile, writeFile } from "node:fs/promises";
import { createWorkspace, createForks } from "@tigrisdata/agent-kit";
import { put, get } from "@tigrisdata/storage";

async function main() {
  try {
    // 1. Read the current trial_id
    const trialIdRaw = await readFile("/logs/artifacts/trial_id", "utf-8");
    const trialId = trialIdRaw.trim().toLowerCase();

    // Normalize workspace name: lowercase and replace underscores with hyphens
    const normalizedTrialId = trialId.replace(/_/g, "-");
    const workspaceName = `harbor-ro-${normalizedTrialId}`;
    console.log(`Workspace name: ${workspaceName}`);

    // 2. Create the editor workspace
    const { data: editorData, error: editorError } = await createWorkspace(workspaceName, {
      ttl: { days: 1 },
      enableSnapshots: true,
      credentials: { role: "Editor" }
    });

    if (editorError) {
      console.error("Error creating workspace:", editorError);
      process.exit(1);
    }

    if (!editorData?.credentials) {
      console.error("Missing editor credentials");
      process.exit(1);
    }

    const editorCreds = editorData.credentials;
    const workspaceBucket = editorData.bucket;

    // 3. Write notes/welcome.txt using editor credentials
    console.log("Writing notes/welcome.txt with editor credentials...");
    const { error: putError } = await put("notes/welcome.txt", "hello readonly", {
      config: {
        bucket: workspaceBucket,
        accessKeyId: editorCreds.accessKeyId,
        secretAccessKey: editorCreds.secretAccessKey,
      }
    });

    if (putError) {
      console.error("Error writing with editor credentials:", putError);
      process.exit(1);
    }

    // 4. Create ReadOnly fork
    const forkPrefix = `harbor-ro-${normalizedTrialId}-readonly`.toLowerCase().replace(/_/g, "-");
    console.log(`Creating fork with prefix: ${forkPrefix}`);
    const { data: forkSet, error: forkError } = await createForks(workspaceBucket, 1, {
      prefix: forkPrefix,
      credentials: { role: "ReadOnly" }
    });

    if (forkError) {
      console.error("Error creating fork:", forkError);
      process.exit(1);
    }

    if (!forkSet?.forks?.[0]?.credentials) {
      console.error("Missing fork credentials");
      process.exit(1);
    }

    const readonlyCreds = forkSet.forks[0].credentials;
    const forkBucket = forkSet.forks[0].bucket;
    console.log(`Fork bucket: ${forkBucket}`);

    // 5. Attempt forbidden write with ReadOnly credentials
    console.log("Attempting forbidden write with ReadOnly credentials...");
    const { error: forbiddenError } = await put("notes/forbidden.txt", "should be rejected", {
      config: {
        bucket: forkBucket,
        accessKeyId: readonlyCreds.accessKeyId,
        secretAccessKey: readonlyCreds.secretAccessKey,
      }
    });

    if (!forbiddenError) {
      console.error("Error: Forbidden write unexpectedly succeeded!");
      process.exit(1);
    }

    console.log("Write denial captured as expected.");
    const denial = `${forbiddenError.name ?? "Error"}: ${forbiddenError.message ?? JSON.stringify(forbiddenError)}`;
    await writeFile("/home/user/tigris-task/write-denial.log", denial, "utf-8");

    // 6. Successful read with ReadOnly credentials
    console.log("Reading back notes/welcome.txt with ReadOnly credentials...");
    const { data: readbackData, error: readbackError } = await get("notes/welcome.txt", "string", {
      config: {
        bucket: forkBucket,
        accessKeyId: readonlyCreds.accessKeyId,
        secretAccessKey: readonlyCreds.secretAccessKey,
      }
    });

    if (readbackError) {
      console.error("Error reading with ReadOnly credentials:", readbackError);
      process.exit(1);
    }

    if (readbackData !== "hello readonly") {
      console.error(`Unexpected readback content: "${readbackData}"`);
      process.exit(1);
    }

    await writeFile("/home/user/tigris-task/readback.txt", readbackData, "utf-8");
    console.log("Readback successful.");

    console.log("Task completed successfully.");
    process.exit(0);
  } catch (err) {
    console.error("Unhandled error:", err);
    process.exit(1);
  }
}

main();
